def __init__(self, directory: UserDirectory, upstream: Upstream, ledger: Ledger,
              clock: Callable[[], datetime] = _utc_now):
    super().__init__()
    self.directory = directory
    self.upstream = upstream
    self.ledger = ledger
    self.clock = clock
    # Store successful responses for idempotent replay: {(user, request_id): Response}
    self._idempotent_store: Dict[Tuple[str, str], Response] = {}

def handle(self, request: dict) -> Response:
    # Extract basic fields.
    user_id = request.get("user")
    model = request.get("model")
    request_id = request.get("request_id")
    # Idempotent replay check (must be after validating user and model to ensure stored response exists).
    if request_id is not None:
        key = (user_id, request_id)
        stored = self._idempotent_store.get(key)
        if stored:
            # Return a copy with replay header.
            replay_headers = dict(stored.headers)
            replay_headers["X-Idempotent-Replay"] = "true"
            return Response(stored.status, stored.body, replay_headers)
    # Validate user.
    try:
        user = self.directory.get(user_id)
    except Exception:
        return Response(403, {"error": "unknown_user"})
    # Validate model.
    if model not in PRICES:
        return Response(400, {"error": "unknown_model"})
    # Determine month string.
    month = self.clock().strftime("%Y-%m")
    # Admission control for budgeted users.
    budget = self.directory.budget(user_id)
    # Compute worst‑case cost.
    worst_usage = Usage(prompt_tokens=request.get("input_tokens", 0), cached_tokens=0,
                        completion_tokens=request.get("max_tokens", 0))
    worst_cost = request_cost(model, worst_usage)
    spent = self.ledger.spent(user_id, month)
    if budget is not None and spent + worst_cost > budget:
        remaining = budget - spent
        if remaining < Decimal("0"):
            remaining = Decimal("0")
        remaining_str = f"{remaining.quantize(Decimal('0.000001'))}"
        return Response(402, {"error": "budget_exceeded", "remaining": remaining_str})
    # Provider call with retries.
    attempts = 0
    successful_completion = None
    while attempts < 3:
        attempts += 1
        try:
            completion = self.upstream(request)
            successful_completion = completion
            break
        except UpstreamError as e:
            # Charge if usage present.
            if e.usage is not None:
                cost = request_cost(model, e.usage)
                entry = Entry(user_id=user_id, month=month, model=model,
                              usage=e.usage, cost=cost, status="failed_attempt")
                self.ledger.record(entry)
            if not e.retryable:
                break
            # else retry loop continues.
    if successful_completion is None:
        return Response(502, {"error": "upstream_failed", "attempts": attempts})
    # Successful path: charge cost and record.
    usage = successful_completion.usage
    cost = request_cost(model, usage)
    entry = Entry(user_id=user_id, month=month, model=model,
                  usage=usage, cost=cost, status="ok")
    self.ledger.record(entry)
    # Build response body.
    body = {
        "content": successful_completion.content,
        "usage": {"prompt_tokens": usage.prompt_tokens,
                  "cached_tokens": usage.cached_tokens,
                  "completion_tokens": usage.completion_tokens},
        "cost_usd": f"{cost.quantize(Decimal('0.000001'))}",
    }
    headers: Dict[str, str] = {}
    # Budget headers for budgeted users.
    if budget is not None:
        new_spent = self.ledger.spent(user_id, month)
        remaining = budget - new_spent
        if remaining < Decimal("0"):
            remaining = Decimal("0")
        headers["X-Budget-Remaining"] = f"{remaining.quantize(Decimal('0.000001'))}"
        # Warning thresholds.
        if new_spent >= budget:
            headers["X-Budget-Warning"] = "100%"
        elif new_spent >= budget * Decimal("0.8"):
            headers["X-Budget-Warning"] = "80%"
    response = Response(200, body, headers)
    # Store for idempotent replay if request_id set.
    if request_id is not None:
        self._idempotent_store[(user_id, request_id)] = response
    return response

